// One message per alert in Grafana's webhook payload, on system1/drift/<set>.
// Labels outside the question sets' menus are dropped: they would be free text.
const TAG = /^[a-z0-9_-]{1,64}$/;
const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
const alerts = Array.isArray(body.alerts) ? body.alerts : [];
const out = [];
for (const a of alerts) {
  const labels = a.labels || {};
  if (!TAG.test(String(labels.set || '')) || !TAG.test(String(labels.question || ''))) continue;
  const values = a.values || {};
  out.push({
    json: {
      topic: `system1/drift/${labels.set}`,
      message: {
        ts: new Date().toISOString(),
        set: labels.set,
        question: labels.question,
        signal: labels.signal || '',
        status: a.status === 'resolved' ? 'resolved' : 'firing',
        value: typeof values.B === 'number' ? values.B : null,
        summary: String((a.annotations || {}).summary || '').slice(0, 300),
        starts_at: a.startsAt || null,
        ends_at: a.status === 'resolved' ? a.endsAt || null : null,
        fingerprint: String(a.fingerprint || ''),
        // A drift alert asks for a new evaluation, never changes anything itself
        action: 'Run p4n4 ai system1 eval ' + labels.set + ' with recent feedback',
      },
    },
  });
}
return out;
